import React, { useState } from "react";
import {
    Divider,
    Paper,
    Box,
    Avatar,
    IconButton,
    Typography,
    Menu,
    MenuItem,
    Chip,
    useMediaQuery,
} from "@mui/material";
import { useTheme } from "@mui/material/styles";
import FavoriteIcon from "@mui/icons-material/Favorite";
import ChatBubbleOutlineIcon from "@mui/icons-material/ChatBubbleOutline";
import ShareOutlinedIcon from "@mui/icons-material/ShareOutlined";
import MoreVertIcon from "@mui/icons-material/MoreVert";
import ExtensionIcon from "@mui/icons-material/Extension";
import SocialActions, { AboutPublisher } from "./SocialActions";


const placeholderData = {
    componentName: "Component Name",
    componentCategory: "Category",
    likes: 2,
    comments: 2,
};


// ─── Shared Menu ─────────────────────────────────────────────────────────────

function ProfileMenu({ componentName,type }) {
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);

    const categoryChip = (
        <Chip
            label={placeholderData.componentCategory}
            size="small"
            sx={{
                fontSize: 12,
                height: 18,
                maxWidth: 120,
                "& .MuiChip-label": {
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    whiteSpace: "nowrap",
                },
            }}
        />
    );

    return (
        <>
            <IconButton size="small" onClick={(e) => setAnchorEl(e.currentTarget)}>
                <MoreVertIcon />
            </IconButton>

            <Menu
                anchorEl={anchorEl}
                open={open}
                onClose={() => setAnchorEl(null)}
                anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
                transformOrigin={{ vertical: "top", horizontal: "right" }}
            >
                {
                    type !== 'compact' && <>
                        <MenuItem>
                            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                                <Avatar sx={{ width: 36, height: 36 }}>
                                    <ExtensionIcon />
                                </Avatar>
                                <Box>
                                    <Typography sx={{ fontWeight: 600, fontSize: 14 }}>
                                        {componentName || placeholderData.componentName}
                                    </Typography>
                                    {categoryChip}
                                </Box>
                            </Box>
                        </MenuItem>

                        <MenuItem>
                            <ChatBubbleOutlineIcon sx={{ mr: 1 }} fontSize="small" />
                            {placeholderData.comments} Comments
                        </MenuItem>

                        <MenuItem>
                            <FavoriteIcon sx={{ mr: 1 }} fontSize="small" color="error" />
                            {placeholderData.likes} Likes
                        </MenuItem>

                        <MenuItem>
                            <ShareOutlinedIcon sx={{ mr: 1 }} fontSize="small" />
                            Share
                        </MenuItem>
                        <Divider sx={{ my: 0.5 }} />
                    </>
                }
        

                <AboutPublisher />
            </Menu>
        </>
    );
}


// ─── Compact Header (used inside the card) ────────────────────────────────────

function CompactHeader({ componentName }) {
    const categoryChip = (
        <Chip
            label={placeholderData.componentCategory}
            size="small"
            sx={{
                fontSize: 12,
                height: 18,
                maxWidth: 120,
                "& .MuiChip-label": {
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    whiteSpace: "nowrap",
                },
            }}
        />
    );

    return (
        <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 1 }}>
            {/* LEFT */}
            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                <Avatar sx={{ width: 36, height: 36 }}>
                    <ExtensionIcon />
                </Avatar>
                <Box>
                    <Typography sx={{ fontWeight: 600, fontSize: 13 }}>
                        {componentName || placeholderData.componentName}
                    </Typography>
                    {categoryChip}
                </Box>
            </Box>

            {/* RIGHT */}
                <ProfileMenu componentName={componentName} type='compact' />

        </Box>
    );
}


// ─── Full Menu Button (used in AppBar on desktop) ─────────────────────────────

export function ProfileHeaderMenu({ componentName }) {
    return <ProfileMenu componentName={componentName} />;
}


// ─── ProfileWrapper ───────────────────────────────────────────────────────────

export default function ProfileWrapper({
    children,
    isActive,
    isFullScreen,
    componentName,
}) {
    const isFullscreenActive = isActive && isFullScreen;

    const Header = (
        <Box sx={{ px: 1.5, py: 1 }}>
            <CompactHeader componentName={componentName} />
        </Box>
    );

    return (
        <Paper
            elevation={isFullscreenActive || !isActive ? 0 : 1}
            sx={{
                p: isFullscreenActive || !isActive ? 0 : 1.5,
                borderRadius: 1,
                height: "100%",
                display: "flex",
                flexDirection: "column",
                ...(isFullscreenActive || !isActive
                    ? { bgcolor: "transparent", boxShadow: "none", p: 0 }
                    : {}),
            }}
        >
            {!(isFullscreenActive || !isActive) && Header}

            <Box sx={{ mt: isFullscreenActive || !isActive ? 0 : 1, flex: 1 }}>
                {children}
            </Box>

            {!(isFullscreenActive || !isActive) && (
                <Box sx={{ display: "flex", alignItems: "center" }}>
                    <SocialActions compact />
                </Box>
            )}
        </Paper>
    );
}
