import React from 'react';
// import makeStyles from '@mui/styles/makeStyles';
import DayIcon from '@mui/icons-material/BrightnessHigh'
import DarkIcon from '@mui/icons-material/Brightness4'
import NightIcon from '@mui/icons-material/Brightness3'
import LaptopIcon from '@mui/icons-material/Laptop';
import PhoneAndroidIcon from '@mui/icons-material/PhoneAndroid';
import ZoomOutMapIcon from '@mui/icons-material/ZoomOutMap';
import Divider from '@mui/material/Divider';
import Paper from '@mui/material/Paper';
import ToggleButton from '@mui/material/ToggleButton';
import ToggleButtonGroup from '@mui/material/ToggleButtonGroup';
import { useTheme } from '@mui/material/styles';
import ZoomInMapIcon from '@mui/icons-material/ZoomInMap';

export default (props) => {
	const theme = useTheme();
	const { showTopUIOptions, isFullScreen } = props;


	const classes = {
		toggleContainer: {
			margin: theme.spacing(2, 0),
		},
		paper: {
			display: 'flex'
		},
		toggleButton: {
			border: 'none'
		},
		themeIcon: {
			// color: theme.palette.info.contrastText,
			fontSize: '1.0rem',
		},
		divider: {
			margin: theme.spacing(1, 0.5),
			backgroundColor: theme.palette.divider
		},
		grow: {
			flexGrow: 1,
		}
	};

	const handleFormat = (event, newFormat) => {
		if (!newFormat) return;

		props.newUIOptions({
			...props.UIOptions,
			format: newFormat,
		});
	};


	const handleTheme = (event, newTheme) => {
		if (newTheme !== null) {
			props.newUIOptions({ ...props.UIOptions, themeName: newTheme })
		}
	};

	// const classes = useStyles();

	return (
		<Paper
			sx={{
				display: 'flex',
				width: '100%',
				justifyContent: 'center',
				borderRadius: showTopUIOptions ? 1 : 0,
			}}
		>

			<ToggleButtonGroup size="small" value={props.UIOptions.themeName} exclusive onChange={handleTheme} aria-label="text alignment">
				<ToggleButton key={1} value="light" sx={classes.toggleButton} aria-label="light">
					<DayIcon sx={classes.themeIcon} />
				</ToggleButton>,
				<ToggleButton key={2} value="dark" sx={classes.toggleButton} aria-label="dark">
					<DarkIcon sx={classes.themeIcon} />
				</ToggleButton>,
				<ToggleButton key={3} value="lightsOut" sx={classes.toggleButton} aria-label="lightsOut">
					<NightIcon sx={classes.themeIcon} />
				</ToggleButton>,
			</ToggleButtonGroup>



			{
				//Not showing format change on fullscreen because fullscreen route components call switchFullScreen on mount itself
				// So clicking on sidebar/mainline wont work because fullscreen param wont removed
				// only back button navigation for fullscreen
				!isFullScreen && <><Divider light flexItem orientation="vertical" sx={classes.divider} />
					<ToggleButtonGroup size="small" value={props.UIOptions.format} exclusive onChange={handleFormat} aria-label="device">

						<ToggleButton value="mainline" sx={classes.toggleButton} aria-label="mainline">
							Mainline
						</ToggleButton>
						<ToggleButton value="sidebar" sx={classes.toggleButton} aria-label="sidebar">
							Sidebar
						</ToggleButton>
						<ToggleButton value="fullscreen">
							<ZoomOutMapIcon sx={classes.themeIcon} />
						</ToggleButton>
						<ToggleButton key={2} value="mobile" sx={classes.toggleButton} aria-label="mobile">
							<PhoneAndroidIcon sx={classes.themeIcon} />
						</ToggleButton>
					</ToggleButtonGroup>
				</>
			}
		</Paper>
	);
}