import React, { Component } from 'react';
import { ThemeProvider, StyledEngineProvider, createTheme, adaptV4Theme } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemText from '@mui/material/ListItemText';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import Button from '@mui/material/Button';
import HomeIcon from '@mui/icons-material/Home';
import SearchIcon from '@mui/icons-material/Search';
import SettingsIcon from '@mui/icons-material/Settings';
import MenuIcon from '@mui/icons-material/Menu';
import InfoIcon from '@mui/icons-material/Info';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import Snackbar from '@mui/material/Snackbar';
import Alert from '@mui/material/Alert';
import Backdrop from '@mui/material/Backdrop';
import CircularProgress from '@mui/material/CircularProgress';
import themes from './themes';
import HDAppBar from './hDAppBar';
import HDIFrame from './hDIFrame';
import { useLocation, useNavigate } from "react-router-dom";
import ProfileWrapper from './ProfileWrapper';
import { formatHeaderToTitle } from './headerUtils';

const RESOLVE_COMP_PATH = "/nodeapi/search/sandboxNLUEngine";
const GET_QUERY_OBJECT = "/nodeapi/component/sandbox-query-object"
const AUTH_PATH = "/nodeapi/auth";
const globalMarginFromDrawerOpened = "5px 0px 20px 160px"
const globalMarginFromDrawerClosed = "5px 0px 20px 50px";
const componentMargin = '5px 60px 0px 100px'

// ---- sx objects ----
const sidebarSx = {
	width: '50px',
	bgcolor: theme => theme.palette.background.paper,
	borderRight: theme => `1px solid ${theme.palette.divider}`,
	display: 'flex',
	flexDirection: 'column',
	alignItems: 'center',
	pt: 1,
};

const pageWrapperSx = {
	display: 'flex',
	overflowY: 'auto',
	flexDirection: { xs: 'column', sm: 'row' },
	height: 'calc(100vh - 56px)',
	ml: '150px',
	'&::-webkit-scrollbar': {
		width: '0px',
		height: '0px'
	},
	scrollbarWidth: 'none',
	msOverflowStyle: 'none'
};

const tabsWrapper = {
	display: 'flex',
	alignItems: 'center',
	pl: '150px',
	py: 1,
	opacity: 0.6,
	pointerEvents: 'none',
	userSelect: 'none',
}


const resultsWrapperSx = {
	order: { xs: 2, sm: 1 },
	flex: 1,
	pt: 3,
	maxWidth: { xs: '100%', md: '720px' },
	mr: '60px',
};

const dummyResultsWrapper = {
	opacity: 0.5,
	pointerEvents: 'none',
	userSelect: 'none',
	filter: 'grayscale(0.5)',
	cursor: 'not-allowed',
}

const iframeWrapperSx = {
	order: { xs: 1, sm: 2 },
	width: { xs: '100%' },
	borderColor: theme => theme.palette.divider,
	bgcolor: theme => theme.palette.background.paper,
	boxShadow: theme => theme.shadows[3],
	mr: '40px',
	mt: '20px',
	position: 'relative',
	borderRadius: '12px',
	alignSelf: 'flex-start',
};


class HDSandbox extends Component {
	constructor(props) {
		super(props);
		this.state = {
			UIOptions: {
				themeName: 'light',
				format: "sidebar",
				sandbox: true,
				componentStyles:{
					margin:componentMargin // componentMargin needs to be passed to withHD because we need the margin just around the component( which is component + secondary Menu)
				}
			},
			previousFormat: "sidebar",
			resource: props.resource || {},
			searchData: props.searchData.filter(
				searchDataItem => searchDataItem.component.toLowerCase() === props.config.name.toLowerCase()
			),
			iframeKey: Date.now(),
			loaded: false,
			showWarning: false,
			windowWidth: window.innerWidth,
			header: { primary: "", secondary: "", jsx: "" },
			isSearchInProgress: false,
			query: "",
			unload: false
		};
		this.theme = createTheme(themes[this.state.UIOptions.themeName]);
		this.resolveQuery = this.resolveQuery.bind(this);
		this.newUIOptions = this.newUIOptions.bind(this);
		this.onCloseFullScreen = this.onCloseFullScreen.bind(this);
		this.WebSearchHeaderHandler = this.WebSearchHeaderHandler.bind(this);
		this.callInitiateSearch = this.callInitiateSearch.bind(this);
		this.iframeRef = React.createRef();
	}
	timer = null;


	componentDidMount() {
		fetch(AUTH_PATH, {
			credentials: "include",
			headers: { Accept: 'text/json' }
		});
		window.addEventListener("resize", this.handleResize);

		const { location } = this.props;

		const params = new URLSearchParams(location.search);
		const fullscreenParam = params.get('fullscreen');

		if (fullscreenParam) {
			this.setState((prevState) => ({
				UIOptions: {
					...prevState.UIOptions,
					format: 'fullscreen',
				},
			}));
		}
	}

	componentDidUpdate(prevProps) {
		if (prevProps.location.search !== this.props.location.search) {
			const prevParams = new URLSearchParams(prevProps.location.search);
			const currentParams = new URLSearchParams(this.props.location.search);

			const hadFullscreen = prevParams.get('fullscreen');
			const hasFullscreen = currentParams.get('fullscreen');

			if (!hadFullscreen && hasFullscreen) {
				this.setState((prevState) => ({
					previousFormat: prevState.UIOptions.format !== 'fullscreen' ? prevState.UIOptions.format : prevState.previousFormat,
					UIOptions: {
						...prevState.UIOptions,
						format: 'fullscreen',
					},
				}));
			}
		}
	}

	componentWillUnmount() {
		this.clearTimer();
		window.removeEventListener("resize", this.handleResize);
	}

	handleResize = () => {
		this.setState({
			windowWidth: window.innerWidth
		});
	};


	startTimer = () => {
		const { loaded } = this.state;

		this.timer = setTimeout(() => {
			if (!loaded) {
				this.setState({ showWarning: true });
			}
		}, 3000);
	};

	clearTimer = () => {
		if (this.timer) {
			clearTimeout(this.timer);
			this.timer = null;
		}
	};


	componentLoaded = () => {
		this.clearTimer();
		this.setState({
			loaded: true
		})

	}

	unloadStandalone = () => {
		this.setState({ unload: true })
	}

	nluEnginePath(query) {
		const config = {
			name: this.props.config.name,
			triggers: this.props.config.triggers,
			query_format: this.props.config.query_format
		};
		return `${RESOLVE_COMP_PATH}?text=${encodeURIComponent(query)}&config=${encodeURIComponent(JSON.stringify(config))}`;
	}

	resolveQuery(query) {
		this.setState({ isSearchInProgress: true, query });
		const url1 = this.nluEnginePath(query);
		const url2 = `${GET_QUERY_OBJECT}?text=${encodeURIComponent(query)}&app=hd`;

		let url1Data = null;
		let url2Data = null;
		let responseCounter = 0;

		const updateState = (newData) => {
			if (newData && newData.length) {
				this.setState({
					searchData: newData.filter(
						item =>
							item?.component?.toLowerCase() === this.props?.config?.name?.toLowerCase()
					)
				});
			} else {
				this.setState({
					searchData: []
				})
			}
		};

		const handleFinalUpdate = () => {
			responseCounter++;
			if (responseCounter === 2) {
				if (!url1Data?.length && !url2Data?.length) {
					updateState([]);
				}
				const { location, navigate } = this.props;
				const searchParams = new URLSearchParams(location.search);
				if (searchParams.has("fullscreen"))
					searchParams.delete("fullscreen")

				if (searchParams.has("component"))
					searchParams.delete("component");

				const newSearch = searchParams.toString();
				navigate(
					{
						pathname: location.pathname,
						search: newSearch ? `?${newSearch}` : "",
					},
					{ replace: true }
				);
				const newFormat = this.state.UIOptions?.format === 'fullscreen' ? this.state.previousFormat : this.state.UIOptions?.format;

				this.setState({
					iframeKey: Date.now(),
					UIOptions: { ...this.state.UIOptions, format: newFormat },
					isSearchInProgress: false,
					unload: false

				});
			}
		};

		const mergeAndUpdate = () => {
			const base = url1Data ?? [];

			const extraFromUrl2 = url2Data
				? url2Data.filter(
					item2 => !base.some(item1 => item1?.component === item2?.component)
				)
				: [];

			const merged = extraFromUrl2.length > 0
				? [...base, ...extraFromUrl2]
				: base;

			updateState(merged);
		};

		try {
			// First call
			fetch(url1, { credentials: "include", headers: { Accept: "text/json" } })
				.then(res => res.json())
				.then(data1 => {
					url1Data = data1?.searchData ?? [];
					updateState(url1Data);
					if (url2Data !== null) {
						mergeAndUpdate();
					}
				})
				.catch(err => {
					console.error("Error in resolve component call:", err);
					url1Data = [];
				})
				.finally(() => {
					handleFinalUpdate();
				});

			// Second call
			fetch(url2, {
				method: "POST",
				credentials: "include",
				headers: {
					"Content-Type": "application/json",
					Accept: "application/json"
				},
				body: JSON.stringify({
					resource: this.state.resource,
					searchData: {
						component: this.props?.config?.name
					}
				})
			})
				.then(res => res.json())
				.then(data2 => {
					if (data2?.error || !data2?.searchData?.length) {
						url2Data = [];
						return;
					}
					url2Data = data2.searchData;
					if (url1Data !== null) {
						mergeAndUpdate();
					}
				})
				.catch(err => {
					console.error("Error in sandbox query call:", err);
					url2Data = [];
				})
				.finally(() => handleFinalUpdate());

		} catch (error) {
			console.error("Error in resolveQuery:", error);
		}
	}


	newUIOptions(UIOptions) {
		const { navigate, location } = this.props;
		const component = this.props?.config?.name || this.state.searchData?.component;

		if (UIOptions.themeName)
			this.theme = createTheme(adaptV4Theme(themes[UIOptions.themeName]));

		this.setState({
			previousFormat: this.state.UIOptions?.format,
			UIOptions: {
				...this.state.UIOptions,
				...UIOptions,
			},
		});
		const iframe = this.iframeRef.current;
		if (UIOptions.format === 'fullscreen' && iframe) {
			iframe.handleScreenChange({ data: { fullScreen: true } });
		}
	}

	onCloseFullScreen() {
		this.setState((prevState) => ({
			UIOptions: { ...prevState.UIOptions, format: prevState.previousFormat }
		}));
	}

	WebSearchHeaderHandler(header) {
		const formatted = formatHeaderToTitle(header);
		this.setState({ header: formatted });
	}

	callInitiateSearch(queryObj) {
		if (queryObj && typeof queryObj.title === "string") {
			this.resolveQuery(queryObj.title);
		}
	}

	onIframeMount = () => {
		this.clearTimer();
		this.setState(
			{ loaded: false, showWarning: false },
			this.startTimer
		);
	};



	render() {
		const { searchData, iframeKey, UIOptions, unload } = this.state;
		const { location, navigate } = this.props;
		const isMediumUp = this.state.windowWidth >= 900;

		const fakeResults = [
			{ title: "React Documentation", url: "https://react.dev", desc: "Official React documentation and guides." },
			{ title: "MDN Web Docs", url: "https://developer.mozilla.org", desc: "Comprehensive web platform documentation." },
			{ title: "Material UI", url: "https://mui.com", desc: "React UI components for faster development." },
			{ title: "Stack Overflow", url: "https://stackoverflow.com", desc: "Community for developers to learn and share knowledge." },
			{ title: "JavaScript Info", url: "https://javascript.info", desc: "Modern JavaScript tutorials and references." }
		];

		const mobileScreenSize = 600;
		const navdrawerOpen = false;
		const fullScreen = UIOptions.format === 'fullscreen';
		const marginValue = navdrawerOpen ? globalMarginFromDrawerOpened : globalMarginFromDrawerClosed;
		const leftMargin = marginValue && marginValue.length && marginValue.split(' ')[3] ? marginValue.split(' ')[3] : '0px';
		const isMobileScreen = mobileScreenSize && this.state.windowWidth < mobileScreenSize || (UIOptions.sandbox && UIOptions.format === 'mobile');
		const fixedLeft = isMobileScreen ? '0px' : leftMargin;
		const fixedTop = true ? "48px" : "0px"; // isTopGap is effectively true in Sandbox
		const fixedBottom = false ? "48px" : "0px"; // isBottomGap is effectively false in Sandbox
		const fullScreenHeight = `calc(100% - ${fixedTop} - ${fixedBottom})`;
		const defaultBackground = this.theme?.palette?.background?.default;

		const isSearchDataAbsentForNewQuery = !this.state.isSearchInProgress && searchData.length === 0;

		const componentWrapper = (
			<Box
				sx={{
					...iframeWrapperSx,
					maxWidth:
						UIOptions.format === 'mainline'
							? { xs: '100%', sm: 720 }
							: { xs: '100%', sm: 400 },

					padding: UIOptions.format === 'mainline' ? 0 : undefined,
					mr: isMediumUp ? 0 : '40px',
				}}
			>
				<div style={fullScreen ?
					{
						width: `calc(100% - ${fixedLeft})`,
						height: fullScreenHeight,
						position: 'fixed',
						background: defaultBackground,
						top: fixedTop,
						bottom: fixedBottom,
						left: fixedLeft,
						zIndex: 1000
					}
					:
					{
						// display: 'flex'

					}
				}>
					{isSearchDataAbsentForNewQuery || unload ? (
						<Alert
							severity={this.state.query ? "error" : "warning"}
							sx={{
								mb: 2,
								alignItems: 'center',
								borderRadius: '8px',
								boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.05)'
							}}
							action={
								<Button
									color="inherit"
									size="small"
									href={this.state.query
										? "https://hyperdart.com/docs/docs/sandbox/local-environment#case-2-unmatched-query"
										: "https://hyperdart.com/docs/docs/sandbox/local-environment#case-1-empty-query"}
									target="_blank"
									rel="noopener noreferrer"
									sx={{ fontWeight: 600, letterSpacing: '0.5px', textTransform: 'none', whiteSpace: 'nowrap' }}
								>
									know more
								</Button>
							}
						>
							<span style={{ whiteSpace: 'nowrap' }}>
								{this.state.query ? "No Searchdata recieved for this query" : "Empty query. No searchdata recieved"}
							</span>
						</Alert>
					) : ''}
					<ProfileWrapper
						key={iframeKey}
						isActive={this.state.loaded}
						isFullScreen={this.state.UIOptions?.format === 'fullscreen'}
						componentName={this.props?.config?.name || this.state.searchData?.[0]?.component}
					>
						<HDIFrame
							ref={this.iframeRef}
							config={this.props.config}
							onMount={this.onIframeMount}
							location={location}
							navigate={navigate}
							searchData={searchData}
							UIOptions={UIOptions}
							onCloseFullScreen={this.onCloseFullScreen}
							componentLoaded={this.componentLoaded}
							WebSearchHeaderHandler={this.WebSearchHeaderHandler}
							callInitiateSearch={this.callInitiateSearch}
							unloadStandalone={this.unloadStandalone}
						/>
					</ProfileWrapper>
				</div>
			</Box>

		);

		const mobileFrameSx = {
			width: 375,        // typical mobile width
			height: 667,       // typical mobile height
			border: '16px solid #333',
			borderRadius: '36px',
			boxShadow: '0 0 20px rgba(0,0,0,0.5)',
			margin: '20px auto',
			position: 'relative',
			background: '#fff',
			padding: '10px',
			overflow: 'hidden',
			bgcolor: theme => theme.palette.background.paper,
		};

		const appContent = (
			<Box sx={{ bgcolor: theme => theme.palette.background.default }}>
				{/* Dim everything except iframe overlay */}
				{UIOptions.format !== 'fullscreen' && (
					<Box
						sx={{
							position: 'fixed',
							top: 0, left: 0,
							width: '100vw', height: '100vh',
							pointerEvents: 'none',
						}}
					/>
				)}

				{/* Left sidebar menu */}
				{
					UIOptions.format !== 'mobile' && isMediumUp ? <Box sx={{
						position: 'fixed',
						top: 0,
						left: 0,
						bottom: 0,
						...sidebarSx,
					}}>
						<IconButton disabled><MenuIcon /></IconButton>
						<IconButton onClick={() => {
							navigate(-1)
						}}><ChevronLeftIcon /></IconButton>
						<Divider sx={{ width: '100%' }} />
						<IconButton disabled><HomeIcon /></IconButton>
						<IconButton disabled><SearchIcon /></IconButton>
						<IconButton disabled><SettingsIcon /></IconButton>
						<IconButton disabled><InfoIcon /></IconButton>
					</Box> : null
				}


				{/* AppBar with left margin */}
				<Box sx={{ ml: UIOptions.format !== 'mobile' && isMediumUp ? '50px' : 0 }}>
					<HDAppBar
						componentMargin={componentMargin}
						isFullScreen={this.state.UIOptions?.format === 'fullscreen'}
						onSearch={this.resolveQuery}
						query={this.state.query}
						UIOptions={UIOptions}
						newUIOptions={this.newUIOptions}
						componentLoaded={this.state.loaded}
						componentName={this.props?.config?.name || this.state.searchData?.[0]?.component}
						title={this.state.header}
					/>
				</Box>

				{/* Tabs Bar */}
				<Box
					sx={UIOptions.format === 'fullscreen' ? { display: 'none' } : (UIOptions.format === 'mobile' || !isMediumUp) ? { ...tabsWrapper, ml: 0, pl: 0 } : tabsWrapper}
				>
					{['ALL', 'IMAGES', 'VIDEOS', 'NEWS'].map((tab, index) => (
						<Typography
							key={tab}
							variant="button"
							sx={{
								color: index === 0 ? '#e36c3d' : 'text.secondary',
								fontWeight: index === 0 ? 600 : 400,
								border: index === 0 ? '1px solid #e36c3d' : '1px solid transparent',
								borderRadius: '16px',
								px: 2,
								py: 0.5,
								fontSize: "10px"
							}}
						>
							{tab}
						</Typography>
					))}
				</Box>


				{/* Page wrapper */}
				<Box sx={UIOptions.format === 'fullscreen' ? { ...pageWrapperSx, ml: '50px', pl: 0 } : (UIOptions.format === 'mobile' || !isMediumUp) ? { ...pageWrapperSx, ml: 0, pl: 0 } : pageWrapperSx}>
					{/* Left: Search results */}
					{UIOptions.format !== 'fullscreen' ? (
						<Box sx={UIOptions.format !== 'mobile' && isMediumUp ? resultsWrapperSx : { ...resultsWrapperSx, maxWidth: UIOptions.format === 'mainline' ? '720px' : '400px', mr: 0 }}>
							<Typography variant="h6" disabled sx={{ color: theme => theme.palette.text.secondary }} gutterBottom>
								Search Results
							</Typography>
							<Divider sx={{ mb: 2 }} />
							{(UIOptions.format === 'mainline' || UIOptions.format === 'mobile') && componentWrapper}
							<List sx={dummyResultsWrapper} >
								{fakeResults.map((res, i) => (
									<React.Fragment key={i}>
										<ListItem alignItems="flex-start">
											<ListItemText
												primary={
													<a
														// href={res.url}
														// target="_blank"
														rel="noopener noreferrer"
														style={{ color: '#1a0dab', textDecoration: 'none' }}
													>
														{res.title}
													</a>
												}
												secondary={
													<Typography
														sx={{ color: theme => theme.palette.text.secondary }}
														variant="body2"
													>
														{res.desc}
													</Typography>
												}
											/>
										</ListItem>
										{i < fakeResults.length - 1 && <Divider component="li" />}
									</React.Fragment>
								))}
							</List>
						</Box>
					) : null}

					{/* Right: HDIFrame sidebar */}
					{(UIOptions.format === 'sidebar' || UIOptions.format === 'fullscreen') && componentWrapper}
				</Box>
			</Box>
		);

		return (
			<StyledEngineProvider injectFirst>
				<ThemeProvider theme={this.theme}>
					{UIOptions.format === 'mobile' ? (
						<Box sx={{ position: 'relative', display: 'flex', justifyContent: 'center', mt: 4 }}>
							{/* Mobile Frame */}
							<Box sx={mobileFrameSx}>
								{appContent}
							</Box>

							{/* 📏 Dimensions box */}
							<Box
								sx={{
									position: 'absolute',
									top: 20,
									right: 'calc(50% - 375px/2)', // align with right edge of mobile
									fontSize: '12px',
									color: '#fff',
									// bgcolor: 'rgba(0,0,0,0.7)',
									px: 1,
									py: 0.5,
									borderRadius: '6px',
								}}
							>
								375 × 667 px
							</Box>
						</Box>

					) : (
						appContent
					)}
					<Snackbar
						open={this.state.showWarning}
						anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
						autoHideDuration={6000}
						onClose={() => this.setState({ showWarning: false })}
					>
						<Alert
							onClose={() => this.setState({ showWarning: false })}
							severity="warning"
							variant="filled"
							sx={{ width: '100%' }}
						>
							Component did not signal <b>componentLoaded</b> within 3 seconds
						</Alert>
					</Snackbar>
					<Backdrop
						sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 9999 }}
						open={this.state.isSearchInProgress}
					>
						<CircularProgress color="inherit" />
					</Backdrop>
				</ThemeProvider>
			</StyledEngineProvider>
		);
	}

}

function HDSandboxWithRouter(props) {
	const location = useLocation();
	const navigate = useNavigate();
	return <HDSandbox {...props} location={location} navigate={navigate} />;
}

export default HDSandboxWithRouter;
